<?php requireRole(['Administrator','Editor']);require_once __DIR__.'/../app/layout.php';$pdo=db();$year=(int)($_GET['year']??date('Y'));$byArea=$pdo->prepare('SELECT a.name area,COUNT(*) lines,SUM(p.quantity) qty,SUM(p.quantity*p.unit_price) abc FROM ppmp_items p JOIN areas a ON a.id=p.area_id WHERE p.fiscal_year=? GROUP BY a.id ORDER BY abc DESC');$byArea->execute([$year]);$rows=$byArea->fetchAll();pageStart('Procurement Reports');?><div class="panel"><h2>PPMP Summary by Area/Unit — FY <?=$year?></h2><div class="table-wrap"><table class="table"><tr><th>Area/Unit</th><th>PPMP Lines</th><th>Quantity</th><th>Total ABC</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['area'])?></td><td><?=number_format($r['lines'])?></td><td><?=number_format($r['qty'],2)?></td><td>₱<?=number_format($r['abc'],2)?></td></tr><?php endforeach;?></table></div></div><?php pageEnd();
